import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const origin = "https://www.iasantetravail.com";

const esc = value => String(value).replaceAll("&", "&amp;").replaceAll('"', "&quot;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
const slug = value => String(value).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

const shellHeader = (pageNav = "") => `<a class="skip-link" href="#content">Skip to main content</a>
  <header class="site-header"><nav class="nav" aria-label="Main navigation"><a class="brand" href="/en/">AI &amp; Occupational Health</a></nav>${pageNav}</header>`;

function readingBody({ kicker, h1, lead, sections, date }) {
  const toc = sections.map((section, index) => `<li><a href="#${slug(section.heading) || `section-${index + 1}`}">${section.heading}</a></li>`).join("");
  const prose = sections.map((section, index) => `<h2 id="${slug(section.heading) || `section-${index + 1}`}">${section.heading}</h2>${section.content}`).join("\n");
  return {
    bodyClass: "page-shell-v2 reading-redesign",
    markup: `${shellHeader()}
  <main id="content">
    <header class="article-masthead"><div><p class="article-kicker">${kicker}</p><h1>${h1}</h1><p class="article-deck">${lead}</p><p class="article-byline">By <strong>Dr Charles Broutin</strong>, occupational physician</p></div><dl class="article-metadata"><div><dt>Published</dt><dd>${date}</dd></div><div><dt>Reading time</dt><dd>Approximately 5 minutes</dd></div><div><dt>Type</dt><dd>Analysis</dd></div><div><dt>Topics</dt><dd>AI · Work · Occupational health</dd></div></dl></header>
    <aside class="article-source-banner" aria-label="Sources for this analysis"><div class="article-source-inner"><span>Sources</span><p>Original sources and references are preserved from the French analysis.</p><a href="${sections[0]?.source || "#publication"}">See publication details ↓</a></div></aside>
    <div class="article-body"><aside class="article-aside" aria-label="Article contents"><p class="article-aside-label">In this analysis</p><ol>${toc}</ol></aside><article class="article-prose">${prose}</article><aside class="article-side-note"><p class="article-aside-label">Reading note</p><strong>Interpret in context.</strong><p>This analysis distinguishes established findings, emerging signals and hypotheses requiring further study.</p></aside></div>
    <section class="article-publication" id="publication" aria-label="Publication information"><div class="article-publication-inner"><dl><div><dt>Published</dt><dd>${date}</dd></div><div><dt>Last reviewed</dt><dd>30 August 2026</dd></div><div><dt>Author</dt><dd>Dr Charles Broutin · occupational physician</dd></div><div><dt>Publisher</dt><dd>AI &amp; Occupational Health</dd></div><div><dt>Version</dt><dd>1.0 · published</dd></div><div><dt>Language</dt><dd>English translation of the French analysis</dd></div></dl></div></section>
    <section class="article-end" aria-labelledby="article-end-title"><div class="article-end-inner"><h2 id="article-end-title">Continue exploring AI and real work.</h2><div><p>Find this analysis in the Reading collection alongside research, experiments and field reports.</p><a href="/en/reading/">Return to all readings →</a></div></div></section>
  </main><footer class="site-footer"><p>© 2026 AI &amp; Occupational Health</p></footer>`
  };
}

