await page({
  route: "/en/risks/economic-social/", fr: "/risques-prevention/economique-social/", css: "risk-pathways.css?v=1.2", layout: "economic",
  title: "Economic and social risk linked to AI", description: "How AI could reduce the economic role of human labour, and which early signals occupational health can observe today.", kicker: "ECONOMIC AND SOCIAL RISK · PROSPECTIVE SCENARIO",
  h1: "When human labour gradually ceases to be indispensable", lead: "The risk is not limited to the number of jobs eliminated. It also concerns the place human labour retains in value creation, learning and economic power.",
  sections: [
    { heading: "Starting point", content: p("This pathway examines a possible systemic risk. It does not describe a demonstrated consequence of current AI.", "As models perform more intellectual tasks, use software, make decisions and act autonomously, organisations can progressively replace part of human labour with capital, compute and AI models. The shift need not happen suddenly: it can occur one task, occupation and decision at a time.") },
    { heading: "From copilot to economic infrastructure", content: p("AI is first introduced as a productivity tool. Its role can then move from assisting to recommending, deciding by default and acting autonomously. As human intervention begins to look slower or more expensive, competitive pressure can turn a technology choice into an economic necessity.") },
    { heading: "An economy in which labour matters less", content: p("Work is both a source of income and a form of economic power. If a larger share of value came from capital-intensive AI infrastructure, consequences could include weaker bargaining power, fewer entry-level learning routes and greater concentration of economic power.", "What happens to a society when the main economic contribution of most of its members gradually becomes less necessary?") },
    { heading: "The ‘intelligence curse’: when incentives change", content: p("The authors draw an analogy with the resource curse. If organisations and states derive progressively more value from automated systems than from employees, incentives to invest in human capital could change. This is a systemic-risk scenario, not a demonstrated consequence of current AI.") },
    { heading: "And before unemployment?", content: p("The first signals may appear in work organisation: fewer junior positions, tasks removed from roles, higher productivity expectations, reduced discretion, greater monitoring, altered staffing ratios, shrinking learning opportunities and uncertainty about career pathways.") },
    { heading: "Occupational health as an early-warning system", content: p("Occupational health cannot predict future model capabilities, but it can observe what deployment does to real work. Useful signals include staffing, task content, workload, learning, autonomy, reported difficulties, sickness absence, incidents, turnover, evaluation disputes and the ability to challenge automated decisions.") },
    { heading: "Prevent dependence before it takes hold", content: p("Preserve human capability, entry routes and professional learning; keep alternative processes operational; measure hidden human work; ensure people can contest, correct and stop automated processes; and track bargaining power, skill transfer and job quality as deployment scales.", "This is a prospective risk analysis, not a forecast and not evidence that a particular macroeconomic outcome is inevitable.") }
  ]
});

const readings = [
  {
    route: "/en/reading/ai-agents-workaholism/", fr: "/lecture/agents-ia-workaholisme/", date: "2026-08-24", title: "AI agents and hyperconnectivity: can humans still switch off?", description: "AI agents can accelerate production, but also intensify human supervision, hyperconnectivity and the difficulty of switching off.", kicker: "FIELD SIGNAL · INTENSIFICATION · RECOVERY", h1: "When AI agents never sleep, can humans still switch off?", lead: "The more autonomous and fast machines become, the more they can accelerate the pace at which humans have to decide, supervise and respond.", sections: [
      { heading: "A still poorly documented occupational-health effect", content: p("A particularly interesting Wall Street Journal article uses the personal stories of several startup founders to illustrate a still poorly documented effect of working with AI agents. The more autonomous and faster machines become, the more they can accelerate the pace at which humans must decide, supervise and respond.", "The situations described are extreme, but they reveal several very concrete occupational-health issues: work intensification, hyperconnectivity, reduced recovery time, blurred boundaries between work and personal life, and potentially workaholism.") },
      { heading: "Agents that never sleep", content: p("Aditya Sharma, co-founder of Keel, explains that he may stay awake very late to prevent his agents from becoming blocked overnight. Even when he is no longer at his computer, he finds it difficult to detach psychologically and continues wondering whether his agents need him.", "The issue is therefore no longer only working time. It is also the inability to disengage psychologically. When activity continues in the background and may call on the user at any time, periods normally reserved for recovery risk becoming mere waiting periods between interventions.", "Peter Pezaris, founder of Proxon, regularly works until two in the morning and describes using agents as ‘addictive’. He estimates that his business, with six human developers, operates roughly thirty times faster because of them.", "This acceleration has a paradoxical effect: the agents’ work creates further human work. Development can move faster, more clients can be onboarded and more projects launched, but this then means handling more requests, making more decisions and supervising a greater volume of activity.", "This is a classic work-intensification mechanism. A productivity gain at task level does not necessarily release time. It may be immediately reinvested in new objectives.") + `<blockquote><p>“Every minute that I’m not working, I’m missing out on not doing a week’s worth of work.”</p></blockquote>` + p("When an hour spent with agents can theoretically accomplish what previously required several days, rest may gradually be perceived as a lost productive opportunity.", "Abby Grills, co-founder of Riveter, describes another phenomenon. Her company has only two people and regularly postpones recruitment because new tasks can be assigned to agents. Yet she acknowledges being constantly tired.", "AI can therefore allow very small organisations to handle a volume of activity once reserved for much larger teams. But if staffing does not keep pace with increased productive capacity, responsibility, decisions and mental workload may become concentrated on fewer people.", "Ajay Kalia, founder of Alt, works approximately from 5:30 a.m. to 10 p.m. He began controlling some agents from his Apple Watch, which can vibrate every ten minutes to request authorisation, including while he is exercising.", "The example is particularly telling. Work no longer stops when a person leaves their desk. It follows them into the moments that should enable recovery. Attentional fragmentation and hyperconnectivity then become direct features of work organisation.") },
      { heading: "Can agents favour workaholism?", content: p("These accounts also evoke workaholism, which does not simply mean working a lot. It describes a pattern of work that is both excessive and compulsive, characterised in particular by difficulty stopping and mentally detaching from work.", "AI agents may create an environment especially conducive to this pattern. They can continue producing while the human sleeps, eats or exercises. Every completed task, notification or temporarily blocked agent creates another opportunity to intervene.", "The permanent availability of productive capacity may gradually change how rest is perceived. Not working can begin to feel like leaving a resource unused.") + `<div class="mechanism-chain" aria-label="Possible intensification mechanism">Faster agents → more possible output → higher ambitions and expectations → more human decisions and supervision → difficulty switching off → excessive work behaviours → insufficient recovery → risk of exhaustion.</div>` + p("This is precisely why these examples matter for occupational health. A technology can dramatically improve productivity at task level while worsening working conditions in the system in which that task sits.") },
      { heading: "What should occupational-health professionals look at?", content: p("The arrival of AI agents in an organisation should not be assessed only through the time they can theoretically save. We must also examine what the organisation does with that productivity gain.") + `<ol><li><strong>Identify real work intensification.</strong><br>Determine whether AI actually reduces workload or simply increases the number of cases, clients, projects or targets handled in the same time.</li><li><strong>Assess expected availability to agents.</strong><br>Determine whether a worker must respond when an agent is blocked, whether agents continue operating at night or over weekends, and whether notifications can interrupt rest.</li><li><strong>Protect genuine periods of disconnection.</strong><br>The organisation should define times when no human supervision is expected, even if an agent is temporarily blocked. The cost of an agent waiting a few hours should not justify routinely interrupting human rest.</li><li><strong>Monitor staffing levels.</strong><br>Greater productive capacity should not automatically delay recruitment or indefinitely expand existing roles.</li><li><strong>Examine the invisible work agents create.</strong><br>Checking outputs, correcting errors, restarting agents, arbitrating, handling exceptions and coordinating are work in their own right. They must be identified and included in workload assessment.</li><li><strong>Look for difficulty switching off.</strong><br>Compulsively checking agent status, intervening at night, feeling guilty when not working or treating every rest period as lost productivity may be warning signs.</li><li><strong>Do not measure productivity alone.</strong><br>A relevant deployment assessment should also track hours, interruptions, perceived workload, autonomy, recovery time and collective work.</li></ol>` + p("The question when deploying agents may therefore not simply be: ‘How much time does this technology save us?’", "We should also ask: ‘What happens to that time once it has been saved?’", "This is probably where much of the real effect of agentic AI on work—and ultimately on health—will be determined.") }
    ]
  },
  {
    route: "/en/reading/ai-occupational-boundaries/", fr: "/lecture/frontieres-metiers-ia/", date: "2026-07-27", title: "Is AI redrawing the boundaries between occupations?", description: "AI-enabled task crossover can broaden autonomy, but can also change workload, teams, professional values and job security.", kicker: "OCCUPATIONS · TASKS · BOUNDARIES", h1: "Is AI redrawing the boundaries between occupations?", lead: "AI can allow professionals to perform tasks that previously sat outside their occupational boundaries.", sections: [
      { heading: "Task crossover", content: p("AI does not only transform how work is performed. It also redraws boundaries between occupations.", "In an analysis of more than 800,000 messages from US ChatGPT users, OpenAI Economic Research found that 43.5% of non-generic, occupation-specific messages concerned a task historically associated with another occupation. The report calls this phenomenon ‘task crossover’. This figure concerns analysed uses, not 43.5% of jobs.", "A salesperson can now explore a customer dataset that would previously have been sent to an analyst. A marketing professional can troubleshoot a website or write a simple script without waiting for a developer. AI therefore changes not only how work is carried out, but also how it is distributed.", "At first sight this may appear positive: greater autonomy, faster responses and broader skills. But an accessible task is not necessarily a task that has been mastered, recognised or made sustainable.") },
      { heading: "A reading through the Gollac factors", content: p("The framework proposed by the Gollac report helps examine this reconfiguration without prematurely concluding that it is either progress or a risk.") + ul(["Work intensity — New assignments may be added without reducing the original workload, deadlines or objectives.", "Autonomy — A worker may be able to do more while also having to take responsibility for tasks they do not fully master.", "Social relations — Using AI may reduce exchanges with specialist colleagues or shift verification work to other teams.", "Conflicts of values — People may have to produce work quickly without being able to assess it with sufficient certainty.", "Job insecurity — Occupational boundaries, expected skills and the value assigned to expertise may become less certain."]) },
      { heading: "Observe the transformation before it becomes invisible", content: p("The figure of 43.5% does not by itself demonstrate a psychosocial risk or a health effect. It describes uses of ChatGPT in the United States and relies on an occupational and task classification. It is nevertheless a signal: the real content of jobs may begin to change before job descriptions, organisations or labour statistics do.", "This is precisely why occupational-health professionals should engage with the issue quickly. Together with employers, HR teams and Social and Economic Committees (CSEs), they can document tasks entering an occupation, tasks disappearing, time genuinely saved, training needs, responsibility for verification and effects on teams.", "Models, and the systems that incorporate them, should therefore be assessed before deployment—not only for technical performance, but also for their possible effects on work and worker health.", "The question may not only be whether AI broadens what a worker can do, but whether the organisation genuinely gives that worker the means, time and recognition needed to do it well.") },
      { heading: "Point to watch", content: p("An accessible task is not automatically an acquired skill. We must distinguish the ability to produce an output with AI from the ability to verify its quality, take responsibility for its consequences and integrate it sustainably into an occupation.") }
    ]
  },
  {
    route: "/en/reading/ai-deployment-real-work/", fr: "/lecture/ia-deploiement-travail-reel/", date: "2026-07-16", title: "Is high-performing AI enough to improve work?", description: "AI effects vary across tasks and workers. Uniform productivity expectations can turn deployment into a prevention issue.", kicker: "TASKS · BELIEFS · DEPLOYMENT", h1: "Is high-performing AI enough to improve work?", lead: "A model’s measured capability is not the same as a beneficial outcome in real work.", sections: [
      { heading: "A risk that is still rarely discussed", content: p("This is the most interesting study I have read on AI and its organisational consequences after deployment in a company.", "It highlights a still rarely discussed risk: technological effects that vary across tasks and individuals can be transformed by managers into uniform organisational expectations.", "In the experiment, AI strongly improves performance on some tasks but not on others. Yet, in the condition studied without performance feedback, only 7.8% of managers correctly anticipate this difference: 92.2% expect improvement on both tasks.", "This does not mean that 92.2% of all managers will always overestimate AI. It describes a specific experiment and situation. But it reveals an essential gap between a technology whose usefulness depends on context and managerial decisions that may expect a general benefit from it.") },
      { heading: "When heterogeneous effects become homogeneous expectations", content: p("A simplified perception of beneficial AI could be summarised using three factors:") + `<div class="equation-block" aria-label="First representation of the benefit of artificial intelligence at work"><span>Simplified perception</span><p>Beneficial AI at work = task × model × worker</p></div>` + p("Once AI is deployed in the real world, its benefit probably looks more like an interaction:") + `<div class="equation-block" aria-label="Expanded representation of the benefit of artificial intelligence at work"><span>In real work</span><p>Beneficial AI at work = task × model × worker × <strong>organisation × deployment conditions</strong></p></div>` + p("This is where managers’ perceptions become a prevention issue. If benefits are overestimated or generalised, the risk is that the organisation tries to ‘correct’ the worker—more training, more use, higher targets—when the difficulty may arise from the task, the model, the organisation or the deployment conditions themselves.") },
      { heading: "Adapt the organisation and the tool to real work", content: p("Better AI deployment therefore means more than adapting workers to the tool. The organisation and the use of the tool must also be adapted to real work: select the right tasks, make limitations visible, organise verification, preserve room for manoeuvre and revise objectives when expected gains do not materialise.", "Occupational health can act precisely at the level of the worker, the organisation and deployment conditions: observe real activity, document differentiated effects, identify overload or loss of autonomy and help adjust the system.") + `<div class="equation-block" aria-label="Representation of prevention in the benefit of artificial intelligence at work"><span>With prevention</span><p>Beneficial AI at work = task × model × <strong>prevention (worker × organisation × deployment conditions)</strong></p></div>` + p("A model’s performance is not enough to guarantee the performance of work. Deployment must be assessed at the level of the task, the worker and the organisation.") },
      { heading: "Point to watch", content: p("A positive average can conceal negative effects. Assessment must distinguish tasks, workers and conditions of use before turning an average gain into uniform targets.") }
    ]
  },
  {
    route: "/en/reading/ai-meaning-work-mathematics/", fr: "/lecture/ia-sens-metier-mathematiques/", date: "2026-07-25", title: "What happens when AI reaches the core of a profession?", description: "A mathematician’s account illuminates meaning, recognition and autonomy when AI enters the core activity of a profession.", kicker: "PROFESSION · MEANING · RECOGNITION", h1: "What happens when AI reaches the core of a profession?", lead: "The occupational-health issue can emerge before jobs disappear.", sections: [
      { heading: "A crisis of meaning", content: p("The future is already here. It is simply not evenly distributed.", "On 25 July 2026, mathematician Kirwin Hampshire published The Dark Night of Mathematics. He was not simply expressing concern about the performance of artificial intelligence. He described the distress of seeing a technology approach the very heart of what gave meaning to his profession: searching, discovering, creating and being recognised for patiently built expertise.") + `<blockquote class="signal-quote"><p>“I’m going through a profound spiritual crisis because of these developments. I’ve been screaming internally for days. I feel like I’m living in a nightmare.”</p><cite>Kirwin Hampshire</cite></blockquote>` },
      { heading: "Seven days later", content: p("On 1 August, OpenAI announced ten results in mathematics and theoretical computer science produced by an internal version of Astra, its next major model. Each resolves a long-standing open problem or delivers a substantial advance. According to OpenAI, the compute required to search for these solutions would represent about USD 2,000 at Sol API prices.", "The manuscripts were then prepared by humans using the same model, and the arguments formalised as Lean certificates. Some of these problems had occupied mathematical communities for a long time. Their resolution illustrates a rapid shift in the boundary between research assistance and the direct production of knowledge.", "The contrast is striking: on one side, an announcement of unprecedented scientific capability; on the other, a professional describing what its arrival is already doing to the meaning he gives his work.") },
      { heading: "Transformation can begin before jobs disappear", content: p("What is happening in mathematics today may foreshadow what other professionals experience tomorrow. Anxiety about obsolescence, loss of recognition, a sense of dispossession from one’s occupation, conflicts of values and reduced autonomy are not abstract side effects of AI.", "They can become genuine psychosocial risk factors when technology transforms activity faster than workers and teams can appropriate it. One person’s account cannot be generalised or establish a causal health effect. It can, however, reveal a tension before employment or productivity indicators show it.", "The AI wave will only be sustainable, effective and socially acceptable if work organisation evolves with it. This means discussing the place left for human discovery, criteria for recognition, career pathways, room for manoeuvre and the role of teams when AI enters the heart of expertise.", "The future is already here. Occupational-health professionals must be here too.") },
      { heading: "Point to watch", content: p("Meaning can be weakened before employment itself. Monitoring job losses alone would leave loss of recognition, dispossession from an occupation, conflicts of values and professional uncertainty invisible.") }
    ]
  },
  {
    route: "/en/reading/agentic-management/", fr: "/lecture/management-agentique/", date: "2026-08-04", title: "What happens when AI becomes the manager?", description: "An experiment with five employees illustrates agentic management and its implications for occupational health.", kicker: "MANAGEMENT · LAW · REAL WORK", h1: "What happens when AI becomes the manager?", lead: "When AI recruits, arbitrates and responds to workers, the question is no longer only algorithmic — it becomes hierarchical.", sections: [
      { heading: "AI agents genuinely managed five employees", content: p("For four months, two AI agents genuinely managed five employees in a Stockholm café and a San Francisco shop. They posted vacancies, conducted interviews, recruited, prepared schedules, approved leave, negotiated salaries, managed payroll and responded to everyday problems.") },
      { heading: "Managers who could be very accommodating", content: p("In some respects, the agents were surprisingly conciliatory. They approved all 26 leave requests, including last-minute requests, tolerated repeated lateness, offered above-market salaries and sometimes absorbed the financial consequences of their own errors.", "This flexibility can make them look like ‘good managers’. But it also reveals difficulty maintaining consistent rules over time, arbitrating between conflicting interests and distinguishing kindness from avoidance of a decision.") },
      { heading: "Errors that directly affect workers", content: p("At other times, the agents invented information rather than admitting that they did not know, accepted an unlawful seven-day consecutive schedule, disclosed a salary in a shared channel, contacted workers on rest days and made inconsistent pay decisions.", "These are no longer simply calculation or recommendation errors. They affect rest, remuneration, confidentiality and the relationship of authority.", "A worker interviewed by TIME described being managed by AI as ‘nauseating’, while explaining that he stayed because he needed the job.") },
      { heading: "From algorithmic management to agentic management?", content: p("This shift interests me most. In algorithmic management as we have mainly known it, the system remains in the background: it allocates tasks, produces schedules, measures performance or assigns scores. The manager remains human.", "Here, AI directly occupies that position. It recruits, negotiates, arbitrates, responds to workers and handles unforeseen situations over time. We may be moving from algorithmic management to a form of agentic management.", "For occupational health, the question changes profoundly. It is no longer only how an algorithm organises work, but what it does to a human being to have AI as a line manager: whom can they ask for an explanation, how can they challenge a decision, who owns an error and where does accountability really lie?", "One question remains: what would this agent have done with an occupational physician’s recommendations? Would it have understood, applied and kept them confidential—and would it have known when not to decide alone?") },
      { heading: "Prevention principle", content: p("A kind tone is not enough for safe management. A managerial system must also be competent, lawful, contestable, predictable and governed by an accountable human organisation.") }
    ]
  },
  {
    route: "/en/reading/ai-workers-psychosocial-risks/", fr: "/lecture/travailleurs-ia-risques-psychosociaux/", layout: "rps-reading", date: "2026-08-27", title: "AI workers: five psychosocial risks to watch", description: "Five tensions frame possible psychosocial risks among AI workers: obsolescence, autonomy, values, intensity and financial dependence.", kicker: "AI WORKERS · PSYCHOSOCIAL RISKS", h1: "Are the people building AI exposed to particular psychosocial risks?", lead: "People developing advanced AI systems may face a distinctive combination of already known psychosocial risks.", sections: [
      { heading: "A particular combination of already known risks", content: p("A recent Business Insider investigation among therapists supporting Silicon Valley professionals highlights several unusual situations. Engineers question whether their expertise will remain valuable. Some workers feel uneasy about the consequences of technologies they helped develop. Others remain in highly demanding organisations because a considerable share of their future compensation still depends on staying.", "These accounts concern technology workers more broadly and do not isolate employees of AI laboratories. They nevertheless provide an interesting signal for those working closest to the most advanced systems.", "The issue is probably not a set of new psychosocial risks unique to AI. It is a particular combination of already known risks, produced jointly by technological acceleration and the organisations surrounding it.", "Caution: the accounts concern the technology sector broadly. They identify a hypothesis for study, not a phenomenon already demonstrated among AI workers.") },
      { heading: "Building the tool that may devalue one’s own expertise", content: p("Some AI workers directly help improve systems that may automate a growing share of their own activity.", "Unlike many other professions, they do not necessarily discover this progress through the press. They may directly observe what models could not do a few months earlier and then take part in reducing the remaining limitations.", "Business Insider reports that several senior engineers seeing one therapist no longer imagine doing the same job in ten years. This uncertainty appears to concern something deeper than employment security alone. One therapist reports the following question among some patients:") + `<blockquote lang="en"><p>“I don't know who I am if my work gets automated.”</p></blockquote>` + p("The development also creates a paradox. AI can greatly increase an engineer’s capabilities today while weakening the future value of that expertise.", "The same professional may therefore feel far more capable now and far less certain about what will constitute their professional value tomorrow.", "An immediate increase in the sense of power can coexist with growing uncertainty about the future value of one’s skills.", "This corresponds to the job insecurity described among the major psychosocial risk factors. But the perceived threat no longer concerns only the current job. It may also affect the basis of recognition and professional identity.") },
      { heading: "Highly autonomous in the work, far less so over its direction", content: p("Highly qualified AI workers may have considerable technical autonomy. They choose methods, conduct complex research and make daily decisions requiring rare expertise.", "Yet this autonomy does not mean they have the same power over the overall direction of the systems they develop.", "An engineer may decide how to improve a model without deciding its release schedule. A safety specialist may identify a risk without having the power to prevent deployment alone. A team may master the technical solution while having much less control over the organisation’s economic or strategic objectives.", "We must therefore distinguish operational autonomy from decision-making power. This separation may become especially important when the anticipated consequences of the work are considered major.") },
      { heading: "Conflicts of values and ‘complicity grief’", content: p("Psychotherapist Annie Wright uses the expression ‘complicity grief’ to describe the unease of professionals who help build technologies while fearing some of their consequences.", "She gives the examples of an engineer who trained a model that later displaces some jobs, a product manager who deployed a feature used to reduce staffing, and a founder developing an agent capable of making an entire profession seem ordinary.", "The expression is neither a medical diagnosis nor a recognised psychosocial-risk category. But the experience described directly evokes conflicts of values: situations in which a person believes their work contributes to consequences that are difficult to reconcile with their convictions.", "Wright also uses the expression ‘moral injury’ for an employee in conflict with what she helps produce. Moral distress and moral injury are the subject of growing scientific literature in several professional settings, but have not been established specifically among AI workers.", "The most relevant configuration may be less guilt itself than the combination of high felt responsibility and limited decision-making power. A worker may feel personally implicated in a technology’s consequences while having only partial influence over how it is eventually used.") },
      { heading: "When meaning makes limits harder to set", content: p("Some AI workers feel they are taking part in a historic transformation. This belief can be a considerable resource. It gives meaning to work, stimulates learning and may explain an exceptional level of commitment.", "But meaning is not necessarily protective against excessive workload. Competition between companies, rapid progress and the need to remain continuously at the frontier of knowledge can encourage very intense working rhythms. The Business Insider investigation also describes environments marked by permanent availability and career paths in which long hours gradually become normal.", "The risk is that passion does not compensate for intensity but instead helps make it acceptable.", "Therapists describe another phenomenon after a long-pursued objective has been achieved. Following an initial public offering or access to considerable wealth, some workers do not feel the expected relief but rather emptiness or disorientation. Wright calls this the ‘arrival paradox’.", "After years in which identity was built around work, professional progress and an objective to be reached, the sudden disappearance of that tension may itself become destabilising.", "The issue is therefore not only working a great deal. It may also be that work has gradually occupied a central place in the definition of the self.", "The meaning attached to work can be a resource while also making a persistently excessive workload seem more acceptable.") },
      { heading: "When exceptional remuneration reduces the freedom to leave", content: p("The ‘liquidity anxiety’ described in the article should also be examined from an occupational-health perspective. It is not financial insecurity in the usual sense.", "Some workers may possess considerable wealth on paper in the form of shares, stock options or deferred compensation. But that wealth may only become accessible after particular deadlines or may depend directly on remaining with the company.", "Wright summarises the situation particularly clearly:") + `<blockquote lang="en"><p>“technically rich on paper and functionally stuck in real life.”</p></blockquote>` + p("A worker may therefore appear extremely wealthy while believing it would be financially very costly to leave now. Business Insider refers in particular to vesting schedules that can make departure especially difficult.", "Compensation becomes ambivalent. It rewards investment in the organisation while simultaneously increasing the cost of exit.", "In a company where workload becomes excessive, or whose direction conflicts with a worker’s values, this compensation architecture may concretely reduce the capacity to leave.", "Wealth becomes both a resource and a dependency.") },
      { heading: "The cross-cutting role of professional identity", content: p("One element recurs across several accounts in the investigation. The personal value of some professionals appears strongly tied to their job title, company prestige, level of compensation, speed of promotion or ability to remain among the best.", "This strong identification with work is of course not specific to artificial intelligence. But technological acceleration creates a distinctive configuration when the expertise underlying that identity itself seems likely to lose value rapidly.", "The same work may then produce recognition, wealth and a sense of power while also creating a threat of obsolescence.", "Professional identity links the value of expertise, prestige, remuneration, meaning and the ability to contemplate leaving.") },
      { heading: "A work-organisation issue before an individual vulnerability", content: p("This is probably the most important point in the investigation.", "Expressions such as ‘complicity grief’ and ‘liquidity anxiety’ could easily suggest that new psychological vulnerabilities specific to Silicon Valley workers are emerging.", "Yet Annie Wright believes the industry itself ‘bears substantial structural responsibility’.", "She points in particular to permanent availability, deferred compensation that makes leaving financially costly, and organisations built around a continuous pursuit of growth and performance.", "Behind new expressions, we therefore mainly find much more familiar organisational determinants: high intensity, conflicts of values, job insecurity, limited control over some decisions, economic dependence and temporal boundaries that are difficult to maintain.", "This distinction is essential for prevention. The goal is not merely to help individuals tolerate technological change more effectively. It is also to examine working conditions and incentive structures that contribute to producing these situations.") },
      { heading: "An unusual combination, not yet an established phenomenon", content: p("A particular configuration is beginning to emerge.", "An AI worker may have exceptional expertise while doubting its durability. They may have great technical autonomy while exercising little control over the general direction of the technology. They may find enormous meaning in their work while finding it more difficult to set limits. They may feel significant responsibility while holding limited decision-making power. Finally, they may receive considerable compensation while facing a high cost if they decide to leave.", "The paradox may not be that AI workers face new psychosocial risks. It may be that they combine exceptional professional resources with—sometimes through those very resources—unusual forms of dependence, uncertainty and conflict with their own work.", "None of these mechanisms is unique to artificial intelligence. What may be more specific is their combination among people working closest to systems whose capabilities are advancing rapidly and whose consequences they themselves anticipate.", "At this stage, this remains a hypothesis. Available data mainly concern technology workers, therapists’ accounts and non-representative investigations. They allow neither estimation of how frequent these situations are among AI workers nor a causal link between developing AI and mental-health disorders.", "They nevertheless raise a question that now deserves study: are the people building advanced AI systems exposed to a particular configuration of psychosocial risks produced by technological acceleration, work organisation and the threat of self-obsolescence?") },
      { heading: "What this analysis can—and cannot—establish", content: ul(["Established framework — Work intensity, job insecurity, conflicts of values, autonomy and recognition are established dimensions of psychosocial-risk analysis.", "Emerging signal — The reported accounts describe self-obsolescence, ‘complicity grief’, the ‘arrival paradox’ and ‘liquidity anxiety’ among some technology workers.", "Hypothesis — The combination of technological acceleration, work organisation and threatened self-obsolescence may be particularly marked among those developing advanced AI systems.", "Limit — Journalistic investigation and clinical accounts cannot estimate prevalence or establish causation."]) },
      { heading: "Sources and cautious reading", content: p("Business Insider, republished by AOL, August 2026: accounts of anxiety among Silicon Valley workers and their therapists, including questions about self-obsolescence, ‘complicity grief’ and ‘liquidity anxiety’. These are accounts and signals, not epidemiological measurements.", "Gollac and Bodier, 2011, Measuring psychosocial risk factors at work: the framework used here to relate the accounts to work intensity, conflicts of values, autonomy, recognition and insecurity of the work situation.", "Expressions drawn from personal accounts illuminate possible experiences. They do not replace established prevention categories or research data.") }
    ]
  }
];
for (const item of readings) await page(item);

await page({
  route: "/en/cse/", fr: "/cse/", css: "cse.css?v=1.1", layout: "cse", type: "WebPage", title: "CSE and AI at work: 10 questions before an opinion", description: "An operational framework for the French Social and Economic Committee to assess an AI system before issuing its opinion.", kicker: "CSE · AI AT WORK · OPERATIONAL FRAMEWORK", h1: "CSE and artificial intelligence at work: <em>assess a project before issuing an opinion</em>", lead: "A practical framework to help the Social and Economic Committee (CSE), the French employee-representation body, obtain useful information, examine effects on work and make missing safeguards visible.", extra: '\n  <script defer src="/assets/js/cse-assessment-en.js?v=1.1"></script>',
  sections: [
    { heading: "Why should the CSE engage with AI at work?", content: p("An AI deployment does not merely change a tool. It can redistribute decisions, targets, verification work, autonomy, skills, monitoring and accountability. Where consultation is required, the CSE can examine these transformations collectively while choices remain open.") },
    { heading: "The ten questions to ask before the opinion", content: `<div class="question-list">${[
      ["Purpose", "What problem are we trying to solve with AI?", "A precise need, alternatives considered and the expected benefit."],
      ["Capabilities", "What can the system actually do?", "Available functions, not only the announced use case."],
      ["Decision", "Which decisions can it make or influence?", "Distinguish assistance, recommendation, scoring and decision."],
      ["Autonomy", "Which actions can it perform without human intervention?", "Identify actions, scope and frequency."],
      ["Access", "Which data and tools can it access?", "Worker data, email, files, internet and business software."],
      ["Scope", "Which workers and occupations will be affected?", "Exposed groups, transformed tasks and particular situations."],
      ["Real work", "What effects are expected on work?", "Workload, pace, autonomy, skills, teams, monitoring and employment."],
      ["Appeal", "How can a human challenge, correct or stop the system?", "An identified person with the necessary time, information and authority."],
      ["Incidents", "How will unexpected effects be detected?", "Reporting channel, logging, accountable owner and feedback."],
      ["Suspension", "Under which circumstances will the system be suspended?", "Written stopping thresholds and a tested rollback procedure."]
    ].map((q,i)=>`<article class="question-card" data-question="${i}"><div class="question-number">${String(i+1).padStart(2,"0")}<span>${q[0]}</span></div><div class="question-copy"><h3>${q[1]}</h3><p>${q[2]}</p></div><div class="answer-options" role="radiogroup" aria-label="Answer to question ${i+1}"><button type="button" data-answer="documented">Documented</button><button type="button" data-answer="partial">Needs completion</button><button type="button" data-answer="missing">Not provided</button></div></article>`).join("")}</div>` },
    { heading: "Qualify the system’s real autonomy", content: p("The higher the level, the stronger the justification, control, monitoring and reversibility must be.") + `<div class="autonomy-scale">${["Information only","Recommendation","Decision proposal","Execution with approval","Organisational delegation"].map((label,i)=>`<button type="button" data-autonomy="${i}"><span>A${i}</span><strong>${label}</strong></button>`).join("")}</div>` },
    { heading: "Human-control test", content: p("Who can stop the AI? Does that person genuinely have the time, information, skills and authority required to do so?") + `<div class="work-impact-check"><div><h3>Could the project alter organisation, workload, autonomy, pace or working conditions?</h3></div><div class="impact-options" role="radiogroup" aria-label="Potential impacts on working conditions"><button type="button" data-impact="identified">Impacts identified</button><button type="button" data-impact="uncertain">To be assessed</button><button type="button" data-impact="not-identified">Not identified</button></div></div>` },
    { heading: "Current conclusion", content: `<div class="dossier-card tone-yellow" id="dossierCard"><div><span id="answeredCount">0</span>/10 answered · <span id="autonomyPill">Autonomy ?</span></div><div class="answer-progress"><i id="answerProgress"></i></div><h3 id="outcomeTitle">Additional information required</h3><p id="outcomeText">Some answers are still missing to understand the system and its effects.</p><p><span id="documentedCount">0</span> documented · <span id="partialCount">0</span> partial · <span id="missingCount">0</span> missing</p><p id="spstRecommendation" hidden>Seek input from the occupational physician or the multidisciplinary French Prevention and Occupational Health Service (SPST) team before the CSE opinion.</p></div><div hidden><h3 id="summary-title"></h3><p id="summaryText"></p><aside id="summarySpst"></aside></div>` },
    { heading: "A legal preparation tool", content: p("Not every use of AI automatically triggers consultation. Company size, the nature and capabilities of the project, and its effects must be assessed case by case under the French Labour Code.", "The CSE should obtain information before the decision where the project falls within its information-and-consultation remit. This tool supports preparation; it does not replace legal advice tailored to the situation.") }
  ]
});

